from typing import Sequence

def midpoint_certificate(c: Sequence[int]) -> dict[str, object]:
    deficits = [2*c[k]-c[k-1]-c[k+1] for k in range(1, len(c)-1)]
    failures = [k+1 for k, value in enumerate(deficits) if value < 0]
    return {"deficits": deficits, "violations": failures, "passes": not failures}

from typing import Sequence

def global_slope_audit(c: Sequence[int]) -> dict[str, object]:
    slopes = [c[k]-c[k-1] for k in range(1, len(c))]
    failures = [k+1 for k in range(len(slopes)-1) if slopes[k+1] > slopes[k]]
    return {"slopes": slopes, "ordered": not failures, "violations": failures}

from itertools import combinations, permutations
from typing import Sequence

def principal_coefficients(a: Sequence[Sequence[int]]) -> list[int]:
    n = len(a)
    if any(len(row) != n for row in a):
        raise ValueError("matrix must be square")
    answer: list[int] = []
    for k in range(n+1):
        values: list[int] = []
        for subset in combinations(range(n), k):
            if not subset:
                values.append(0)
            else:
                values.append(max(sum(a[i][j] for i, j in zip(subset, p))
                                  for p in permutations(subset)))
        answer.append(max(values))
    return answer

